  amp(+1, +1) = +four / s(i3, i4) * za(i2, i3) * zba3(i4, i1, i6, i5, i2) / za(i1, i5) / za(i2, i6) / za(i6, i5);
  amp(+1, -1) = four / (s(i3, i4) * s(i5, i6))
